from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(int)
# infer cylinder based on grayscale 60-120 region boundaries for y rows, x<190
for y in range(45,85):
 row=im[y,:190].mean(1)
 # intervals where between 50 and 125; show big contiguous
 m=(row>45)&(row<125)
 inds=np.flatnonzero(m); runs=[]
 if len(inds):
  st=pr=inds[0]
  for q in inds[1:]:
   if q>pr+1:
    if pr-st>=5:runs.append((int(st),int(pr)))
    st=q
   pr=q
  if pr-st>=5:runs.append((int(st),int(pr)))
 print(y,runs)
